        var errors = output.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error).ToList();
        Assert.True(errors.Count == 0, string.Join(Environment.NewLine, errors));
    }

    private static int CountOccurrences(string text, string value)
    {
        var count = 0;
        for (var i = text.IndexOf(value, StringComparison.Ordinal); i >= 0; i = text.IndexOf(value, i + value.Length, StringComparison.Ordinal))
            count++;
        return count;
    }

    [Fact]
    public void StaticHeader_OnMethod_EmittedInGeneratedCode()
    {
        var source = """
            using ZeroAlloc.Rest.Attributes;
            namespace MyApp;
            [ZeroAllocRestClient]
            public interface IFileApi
            {
                [Get("/files/{id}")]
                [Header("Accept", Value = "application/octet-stream")]
                System.Threading.Tasks.Task<string> GetFileAsync(int id, System.Threading.CancellationToken ct = default);
            }
            """;
        var output = GetGeneratedSource(source, "IFileApi.g.cs");
        Assert.Contains("\"Accept\"", output);
        Assert.Contains("\"application/octet-stream\"", output);
        Assert.Contains("TryAddWithoutValidation", output);
    }

    // Issue #354: HttpHeaders.TryAddWithoutValidation sends a null value as an empty header,
    // so a nullable [Header] parameter is only added when it has a value. A non-nullable value
    // type can never be null and is added unconditionally.
    [Fact]
    public void HeaderParam_Nullable_IsAddedOnlyWhenNotNull_AndCompiles()
    {
        var source = """
            #nullable enable
            using ZeroAlloc.Rest.Attributes;
            namespace MyApp;
            [ZeroAllocRestClient]
            public interface IHeaderApi
            {
                [Get("/items")]
                System.Threading.Tasks.Task<string> GetAsync(
                    [Header("X-Ref")] string? reference,
                    [Header("X-Retry")] int? retry,
                    [Header("X-Count")] int count,
                    [Header("X-Plain")] string plain,
                    System.Threading.CancellationToken ct = default);
            }
            """;
        var (output, errors) = CompileGenerated(source, "IHeaderApi.g.cs");

        Assert.Empty(errors);
        Assert.Contains("if (reference is not null)", output);
        Assert.Contains("__request.Headers.TryAddWithoutValidation(\"X-Ref\", __FormatValue(reference));", output);
        Assert.Contains("if (retry is not null)", output);
        Assert.Contains("__request.Headers.TryAddWithoutValidation(\"X-Retry\", __FormatValue(retry));", output);
        Assert.Contains("if (plain is not null)", output);
        Assert.DoesNotContain("if (count is not null)", output);
        Assert.Contains("__request.Headers.TryAddWithoutValidation(\"X-Count\", __FormatValue(count));", output);
    }

