    [Fact]
    public void ConflictingBodyAndFormBody_ReportsDiagnostic()
    {
        var source = """
            using System.Collections.Generic;
            using ZeroAlloc.Rest.Attributes;
            namespace MyApp;
            [ZeroAllocRestClient]
            public interface ITokenApi
            {
                [Post("/token")]
                System.Threading.Tasks.Task<string> BadAsync(
                    [Body] string body,
                    [FormBody] Dictionary<string, string> form,
                    System.Threading.CancellationToken ct = default);
            }
            """;
        var compilation = CSharpCompilation.Create(
            "TestAssembly",
            new[] { CSharpSyntaxTree.ParseText(source) },
            Basic.Reference.Assemblies.Net100.References.All
                .Append(MetadataReference.CreateFromFile(AttributesAssembly.Location)),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        var generator = new RestClientGenerator();
        var driver = CSharpGeneratorDriver
            .Create(generator)
            .RunGenerators(compilation);

        var result = driver.GetRunResult();
        var diagnostic = Assert.Single(result.Results[0].Diagnostics, d => d.Id == "ZRA001");
        Assert.NotEqual(Location.None, diagnostic.Location);
        Assert.Equal("BadAsync", source.Substring(diagnostic.Location.SourceSpan.Start, diagnostic.Location.SourceSpan.Length));
        Assert.Equal(7, diagnostic.Location.GetLineSpan().StartLinePosition.Line);
        Assert.Equal(
            "Method 'BadAsync' has both [Body] and [FormBody] parameters; only one is allowed",
            diagnostic.GetMessage(System.Globalization.CultureInfo.InvariantCulture));
    }

    // Rest 3.0: IRestSerializer carries no trim annotations, so a generated method calls it with
    // no suppression, and ILC has nothing to hide.
    [Fact]
    public void GeneratedMethods_CarryNoTrimSuppression()
    {
        const string source = """
            using System.Threading;
            using System.Threading.Tasks;
            using ZeroAlloc.Rest.Attributes;
            namespace MyApp;
            [ZeroAllocRestClient]
            public interface IPingApi
            {
                [Get("/ping")]
                Task<string> PingAsync(CancellationToken ct = default);
            }
            """;

        var generated = GetGeneratedSource(source, "IPingApi.g.cs");

        Assert.Contains("PingAsync(", generated);
        Assert.DoesNotContain("UnconditionalSuppressMessage", generated);
        Assert.DoesNotContain("#pragma", generated);
    }

    private static string GetGeneratedSource(string source, string hintName)
    {
        var compilation = CSharpCompilation.Create(
            "TestAssembly",
            new[] { CSharpSyntaxTree.ParseText(source) },
            Basic.Reference.Assemblies.Net100.References.All
                .Append(MetadataReference.CreateFromFile(AttributesAssembly.Location)),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        var generator = new RestClientGenerator();
        var driver = CSharpGeneratorDriver
            .Create(generator)
            .RunGenerators(compilation);

        var result = driver.GetRunResult();
        var file = result.Results[0].GeneratedSources
            .FirstOrDefault(f => f.HintName == hintName);
        return file.SourceText?.ToString() ?? string.Empty;
    }

    private static string GetGeneratedSourceWithResults(string source, string hintName)
    {
        var compilation = CSharpCompilation.Create(
            "TestAssembly",
            new[] { CSharpSyntaxTree.ParseText(source) },
            Basic.Reference.Assemblies.Net100.References.All
                .Append(MetadataReference.CreateFromFile(AttributesAssembly.Location))
                .Append(MetadataReference.CreateFromFile(ResultsAssembly.Location)),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        var generator = new RestClientGenerator();
        var driver = CSharpGeneratorDriver
            .Create(generator)
            .RunGenerators(compilation);

        var result = driver.GetRunResult();
        var file = result.Results[0].GeneratedSources
            .FirstOrDefault(f => f.HintName == hintName);
        return file.SourceText?.ToString() ?? string.Empty;
    }
